// Custom Worker entry: the OpenNext worker only handles `fetch`, so this wraps it
// to add the Cron Trigger (wrangler.jsonc → triggers.crons) that runs the
// collector. The cron simply calls the app's own /api/ingest route, so the
// collector logic lives in one place (lib/ingest/run.ts).
//
// Requires the INGEST_SECRET secret: /api/ingest rejects unauthenticated calls
// in production.

// Generated by `opennextjs-cloudflare build`.
import handler from "./.open-next/worker.js";

const worker = {
  fetch: handler.fetch,

  /**
   * @param {ScheduledController} controller
   * @param {Record<string, string>} env
   * @param {ExecutionContext} ctx
   */
  async scheduled(controller, env, ctx) {
    const request = new Request("https://cron.internal/api/ingest", {
      method: "POST",
      headers: env.INGEST_SECRET ? { authorization: `Bearer ${env.INGEST_SECRET}` } : {},
    });
    ctx.waitUntil(
      handler.fetch(request, env, ctx).then(async (res) => {
        const body = await res.text();
        if (res.ok) console.log(`[cron ${controller.cron}] ingest:`, body);
        else console.error(`[cron ${controller.cron}] ingest failed (${res.status}):`, body);
      }),
    );
  },
};

export default worker;
